exercise.referenceSolution:
#include <iostream>
#include <print>
#include <string>

struct Vec2 {
    long long x = 0;
    long long y = 0;

    bool operator==(const Vec2 &) const = default;
};

Vec2 operator+(Vec2 a, Vec2 b) {
    return {a.x + b.x, a.y + b.y};
}

Vec2 operator-(Vec2 a, Vec2 b) {
    return {a.x - b.x, a.y - b.y};
}

Vec2 operator*(Vec2 a, long long k) {
    return {a.x * k, a.y * k};
}

int main() {
    Vec2 a;
    std::string op;
    while (std::cin >> a.x >> a.y >> op) {
        if (op == "*") {
            long long k;
            std::cin >> k;
            Vec2 r = a * k;
            std::println("({}, {})", r.x, r.y);
            continue;
        }
        Vec2 b;
        std::cin >> b.x >> b.y;
        if (op == "==") {
            std::println("{}", a == b ? "да" : "нет");
        } else {
            Vec2 r = op == "+" ? a + b : a - b;
            std::println("({}, {})", r.x, r.y);
        }
    }
    return 0;
}

