#include <algorithm>
#include <iostream>
#include <print>
#include <string>
#include <vector>

struct Time {
    int hours = 0;
    int minutes = 0;

    auto operator<=>(const Time &) const = default;
};

struct Event {
    Time time;
    std::string name;
};

Time read_time() {
    Time t;
    char colon;
    std::cin >> t.hours >> colon >> t.minutes;
    return t;
}

int main() {
    Time now = read_time();
    std::vector<Event> events;
    while (true) {
        Time t = read_time();
        std::string name;
        if (!(std::cin >> name)) {
            break;
        }
        events.push_back({t, name});
    }
    std::ranges::stable_sort(events, {}, &Event::time);
    for (const Event &e : events) {
        std::println("{:02}:{:02} {}", e.time.hours, e.time.minutes, e.name);
    }
    auto ahead = std::ranges::count_if(events, [&now](const Event &e) { return e.time > now; });
    std::println("впереди: {}", ahead);
    return 0;
}

