#include <iostream>
#include <print>
#include <string>
#include <vector>

class Matrix {
public:
    Matrix(int rows, int cols) : rows_(rows), cols_(cols), cells_(static_cast<std::size_t>(rows * cols)) {}

    int rows() const {
        return rows_;
    }

    int cols() const {
        return cols_;
    }

    long long &operator[](int i, int j) {
        return cells_[static_cast<std::size_t>(i * cols_ + j)];
    }

    long long operator[](int i, int j) const {
        return cells_[static_cast<std::size_t>(i * cols_ + j)];
    }

private:
    int rows_;
    int cols_;
    std::vector<long long> cells_;
};

Matrix operator*(const Matrix &a, const Matrix &b) {
    Matrix c(a.rows(), b.cols());
    for (int i = 0; i < a.rows(); i++) {
        for (int j = 0; j < b.cols(); j++) {
            for (int k = 0; k < a.cols(); k++) {
                c[i, j] += a[i, k] * b[k, j];
            }
        }
    }
    return c;
}

Matrix read_matrix() {
    int r, c;
    std::cin >> r >> c;
    Matrix m(r, c);
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            std::cin >> m[i, j];
        }
    }
    return m;
}

int main() {
    Matrix a = read_matrix();
    Matrix b = read_matrix();
    if (a.cols() != b.rows()) {
        std::println("размеры не совпадают");
        return 0;
    }
    Matrix c = a * b;
    for (int i = 0; i < c.rows(); i++) {
        std::string line;
        for (int j = 0; j < c.cols(); j++) {
            line += (j ? " " : "") + std::to_string(c[i, j]);
        }
        std::println("{}", line);
    }
    return 0;
}

